/*
 * hooks.c - netfilter entry points.
 *
 *   IPv4 PRE_ROUTING  FIRST     filter    packets arriving (forwarded or local)
 *   IPv4 LOCAL_OUT    FIRST     filter    packets generated by this host
 *   IPv4 PRE_ROUTING  NAT_DST   DNAT, un-SNAT of replies     (generation check)
 *   IPv4 POST_ROUTING NAT_SRC   SNAT, un-DNAT of replies     (generation check)
 *   IPv4 POST_ROUTING LAST      final accept accounting
 *   IPv4 LOCAL_IN     LAST      generation check, final accept accounting
 *   IPv6 PRE_ROUTING / LOCAL_OUT FIRST   drop IPv6 on managed zone interfaces
 *
 * Every packet is filtered exactly once, before any address is rewritten,
 * so rules are written against the addresses the sender used (for a DNAT
 * service: the published address and port).
 *
 * Filter order:
 *   gate (commit in progress) -> header checks (fragment, protocol, parse)
 *   -> anti-spoof for the ingress zone -> flow lookup (with ingress interface
 *   check) -> first matching rule -> default action -> create the flow
 *   (with its NAT plan). Any failure to create required state drops.
 *
 * The filter stamps the active generation into skb->mark. myfw owns
 * skb->mark on this host: nothing else may use fwmark (see
 * docs/transaction-design.md). The later hooks drop packets whose mark is
 * not the active generation, so no packet mixes two policies.
 */
#include <linux/netfilter_ipv4.h>
#include <linux/netfilter_ipv6.h>
#include <linux/netdevice.h>
#include <net/net_namespace.h>
#include "fw.h"

static bool src_allowed(const struct fw_zone_k *z, u32 saddr)
{
	u32 i;

	if (!z->n_srcs)
		return true;
	for (i = 0; i < z->n_srcs; i++)
		if (fw_ip_match(saddr, z->srcs[i].addr, z->srcs[i].mask))
			return true;
	return false;
}

static bool port_in(u16 p, u16 lo, u16 hi)
{
	return p >= lo && p <= hi;
}

static bool rule_matches(const struct fw_rule_spec *r, const struct fw_tuple *t,
			 bool local_out, int zone)
{
	if (r->scope == FW_SCOPE_INGRESS && local_out)
		return false;
	if (r->scope == FW_SCOPE_LOCAL_OUT && !local_out)
		return false;
	if (r->zone && (local_out || r->zone != zone))
		return false;
	if (r->proto && r->proto != t->proto)
		return false;
	if (!fw_ip_match(t->saddr, r->saddr, r->smask) || !fw_ip_match(t->daddr, r->daddr, r->dmask))
		return false;
	if (t->proto == IPPROTO_TCP || t->proto == IPPROTO_UDP)
		return port_in(t->sport, r->sport_min, r->sport_max) &&
		       port_in(t->dport, r->dport_min, r->dport_max);
	return true;
}

static void nat_plan(const struct fw_snap *s, const struct fw_tuple *t, bool local_out,
		     int zone, struct fw_nat_plan *p)
{
	u32 i;

	memset(p, 0, sizeof(*p));
	/* DNAT first: only for packets arriving on an interface */
	for (i = 0; i < s->nn && !local_out; i++) {
		const struct fw_nat_spec *n = &s->nats[i].s;

		if (n->type != FW_NAT_DNAT || n->proto != t->proto || n->daddr != t->daddr ||
		    n->dport != t->dport || (n->zone && n->zone != zone))
			continue;
		p->type = FW_NAT_DNAT;
		p->to_addr = n->to_addr;
		p->port_min = p->port_max = n->to_port_min;
		atomic64_inc(&s->nats[i].hits);
		return;
	}
	for (i = 0; i < s->nn; i++) {
		const struct fw_nat_spec *n = &s->nats[i].s;

		if (n->type != FW_NAT_SNAT || (n->proto && n->proto != t->proto))
			continue;
		if (n->zone && (local_out || n->zone != zone))
			continue;
		if (!fw_ip_match(t->saddr, n->saddr, n->smask))
			continue;
		if (n->dmask ? !fw_ip_match(t->daddr, n->daddr, n->dmask)
			     : fw_ip_match(t->daddr, n->saddr, n->smask))
			continue;       /* default: only traffic leaving the source subnet */
		p->type = FW_NAT_SNAT;
		p->to_addr = n->to_addr;
		p->port_min = n->to_port_min;
		p->port_max = n->to_port_max;
		p->out_ifindex = s->nats[i].out_ifindex;
		atomic64_inc(&s->nats[i].hits);
		return;
	}
}

static unsigned int drop_ev(const struct sk_buff *skb, const struct fw_snap *s,
			    const struct fw_tuple *t, u32 len, int reason, int zslot,
			    int ifidx, const char *rule)
{
	fw_event_packet(t, len, s->gen, FW_ACT_DROP, reason, zslot < 0 ? 0 : zslot, ifidx, rule);
	return fw_drop(skb, reason, zslot);
}

static unsigned int fw_filter(void *priv, struct sk_buff *skb,
			      const struct nf_hook_state *state)
{
	struct fw_snap *s = rcu_dereference(fw_active);
	bool local_out = state->hook == NF_INET_LOCAL_OUT;
	const struct net_device *in = state->in;
	bool from_lo = !local_out && in && (in->flags & IFF_LOOPBACK);
	int ifidx = (local_out || from_lo) ? FW_IF_LOCAL : (in ? in->ifindex : 0);
	int zone = (local_out || !in) ? 0 : fw_zone_of(s, in->ifindex);
	int zslot = local_out ? FW_ZONE_LOCAL : zone;
	const struct fw_rule_k *hit = NULL;
	struct fw_nat_plan plan;
	struct fw_tuple t = {};
	unsigned int action;
	bool log;
	int reason, r;
	u8 flags;
	u32 len, i;

	if (READ_ONCE(fw_gate))
		return fw_drop(skb, FW_R_GATE, zslot);

	reason = fw_pkt_check(skb, &t, &flags);
	len = fw_pkt_payload_len(skb);
	if (reason)
		return drop_ev(skb, s, &t, len, reason, zslot, ifidx, NULL);

	if (zone && !src_allowed(&s->zones[zone - 1], t.saddr))
		return drop_ev(skb, s, &t, len, FW_R_SPOOF, zslot, ifidx, s->zones[zone - 1].name);

	r = fw_conn_lookup(&t, flags, len, ifidx, s->gen);
	if (r < 0)
		return drop_ev(skb, s, &t, len, -r, zslot, ifidx, NULL);
	if (r > 0) {
		fw_stat_add(FW_S_STATEFUL, 1);
		skb->mark = s->gen;
		return NF_ACCEPT;
	}

	for (i = 0; i < s->nr; i++)
		if (rule_matches(&s->rules[i].s, &t, local_out, zone)) {
			hit = &s->rules[i];
			break;
		}
	if (hit) {
		action = hit->s.action;
		log = hit->s.log;
		atomic64_inc((atomic64_t *)&hit->flows);
		atomic64_add(len, (atomic64_t *)&hit->bytes);
	} else {
		action = s->default_action;
		log = s->default_log;
	}

	if (action != FW_ACT_ACCEPT) {
		fw_stat_add(FW_S_NEW_DROP, 1);
		if (log)
			fw_event_packet(&t, len, s->gen, FW_ACT_DROP,
					hit ? FW_R_RULE : FW_R_DEFAULT, zslot, ifidx,
					hit ? hit->s.id : NULL);
		return fw_drop(skb, hit ? FW_R_RULE : FW_R_DEFAULT, zslot);
	}

	nat_plan(s, &t, local_out, zone, &plan);
	r = fw_conn_add(&t, len, ifidx, s->gen, &plan, hit ? hit->s.id : "");
	if (r == -EEXIST) {
		/* another CPU created this flow a moment ago: use it */
		r = fw_conn_lookup(&t, flags, 0, ifidx, s->gen);
		if (r > 0) {
			skb->mark = s->gen;
			return NF_ACCEPT;
		}
		return drop_ev(skb, s, &t, len, r < 0 ? -r : FW_R_NAT_STATE, zslot, ifidx, NULL);
	}
	if (r) {
		fw_stat_add(FW_S_FLOW_FAIL, 1);
		reason = r == -ENOSPC ? FW_R_FLOW_FULL : r == -ENOMEM ? FW_R_NOMEM : FW_R_NAT_STATE;
		return drop_ev(skb, s, &t, len, reason, zslot, ifidx, hit ? hit->s.id : NULL);
	}
	fw_stat_add(FW_S_NEW_ACCEPT, 1);
	if (log)
		fw_event_packet(&t, len, s->gen, FW_ACT_ACCEPT, FW_R_NONE, zslot, ifidx,
				hit ? hit->s.id : NULL);
	skb->mark = s->gen;
	return NF_ACCEPT;
}

static bool gen_ok(const struct sk_buff *skb, const struct fw_snap *s)
{
	return skb->mark == s->gen;
}

static unsigned int fw_nat_in(void *priv, struct sk_buff *skb,
			      const struct nf_hook_state *state)
{
	struct fw_snap *s = rcu_dereference(fw_active);
	struct fw_tuple t;
	u8 flags;

	if (!gen_ok(skb, s))
		return fw_drop(skb, FW_R_GENERATION, -1);
	if (fw_pkt_check(skb, &t, &flags))
		return fw_drop(skb, FW_R_PARSE, -1);
	return fw_conn_nat_pre(skb, &t, s->gen);
}

static unsigned int fw_nat_out(void *priv, struct sk_buff *skb,
			       const struct nf_hook_state *state)
{
	struct fw_snap *s = rcu_dereference(fw_active);
	struct fw_tuple t;
	u8 flags;

	if (!gen_ok(skb, s))
		return fw_drop(skb, FW_R_GENERATION, -1);
	if (fw_pkt_check(skb, &t, &flags))
		return fw_drop(skb, FW_R_PARSE, -1);
	return fw_conn_nat_post(skb, &t, s->gen, state->out);
}

static int zone_slot_of_iif(const struct fw_snap *s, int iif)
{
	struct net_device *dev;
	int slot = FW_ZONE_LOCAL;

	if (!iif)
		return FW_ZONE_LOCAL;           /* generated by this host */
	dev = dev_get_by_index_rcu(&init_net, iif);
	if (dev && !(dev->flags & IFF_LOOPBACK))
		slot = fw_zone_of(s, iif);
	return slot;
}

static unsigned int fw_final_out(void *priv, struct sk_buff *skb,
				 const struct nf_hook_state *state)
{
	struct fw_snap *s = rcu_dereference(fw_active);

	/* loopback traffic is counted once, when it is delivered (LOCAL_IN) */
	if (state->out && (state->out->flags & IFF_LOOPBACK))
		return NF_ACCEPT;
	fw_count_accept(skb, zone_slot_of_iif(s, skb->skb_iif));
	return NF_ACCEPT;
}

static unsigned int fw_local_in(void *priv, struct sk_buff *skb,
				const struct nf_hook_state *state)
{
	struct fw_snap *s = rcu_dereference(fw_active);
	struct fw_tuple t;
	u8 flags;

	if (!gen_ok(skb, s))
		return fw_drop(skb, FW_R_GENERATION, -1);
	if (!fw_pkt_check(skb, &t, &flags))
		fw_conn_local_in(&t, s->gen);
	fw_count_accept(skb, (state->in && (state->in->flags & IFF_LOOPBACK)) ?
			     FW_ZONE_LOCAL : zone_slot_of_iif(s, state->in ? state->in->ifindex : 0));
	return NF_ACCEPT;
}

static unsigned int fw_ipv6(void *priv, struct sk_buff *skb,
			    const struct nf_hook_state *state)
{
	struct fw_snap *s = rcu_dereference(fw_active);
	const struct net_device *dev = state->hook == NF_INET_LOCAL_OUT ? state->out : state->in;
	int zone;

	if (!dev)
		return NF_ACCEPT;
	zone = fw_zone_of(s, dev->ifindex);
	if (!zone)
		return NF_ACCEPT;               /* only managed zone interfaces */
	return fw_drop(skb, FW_R_IPV6, zone);
}

static const struct nf_hook_ops fw_ops[] = {
	{ .hook = fw_filter,    .pf = NFPROTO_IPV4, .hooknum = NF_INET_PRE_ROUTING,  .priority = NF_IP_PRI_FIRST },
	{ .hook = fw_filter,    .pf = NFPROTO_IPV4, .hooknum = NF_INET_LOCAL_OUT,    .priority = NF_IP_PRI_FIRST },
	{ .hook = fw_nat_in,    .pf = NFPROTO_IPV4, .hooknum = NF_INET_PRE_ROUTING,  .priority = NF_IP_PRI_NAT_DST },
	{ .hook = fw_nat_out,   .pf = NFPROTO_IPV4, .hooknum = NF_INET_POST_ROUTING, .priority = NF_IP_PRI_NAT_SRC },
	{ .hook = fw_final_out, .pf = NFPROTO_IPV4, .hooknum = NF_INET_POST_ROUTING, .priority = NF_IP_PRI_LAST },
	{ .hook = fw_local_in,  .pf = NFPROTO_IPV4, .hooknum = NF_INET_LOCAL_IN,     .priority = NF_IP_PRI_LAST },
	{ .hook = fw_ipv6,      .pf = NFPROTO_IPV6, .hooknum = NF_INET_PRE_ROUTING,  .priority = NF_IP6_PRI_FIRST },
	{ .hook = fw_ipv6,      .pf = NFPROTO_IPV6, .hooknum = NF_INET_LOCAL_OUT,    .priority = NF_IP6_PRI_FIRST },
};

int fw_hooks_init(void)
{
	return nf_register_net_hooks(&init_net, fw_ops, ARRAY_SIZE(fw_ops));
}

void fw_hooks_exit(void)
{
	nf_unregister_net_hooks(&init_net, fw_ops, ARRAY_SIZE(fw_ops));
}
